// ListReplies returns up to row_limit replies of a thread older than the
// cursor (all when before is NULL), newest first, with their authors.
func (q *Queries) ListReplies(ctx context.Context, arg ListRepliesParams) ([]ListRepliesRow, error) {
	rows, err := q.db.Query(ctx, listReplies, arg.RootID, arg.Before, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListRepliesRow
	for rows.Next() {
		var i ListRepliesRow
		if err := rows.Scan(
			&i.ID,
			&i.ChannelID,
			&i.AuthorID,
			&i.Body,
			&i.Nonce,
			&i.CreatedAt,
			&i.EditedAt,
			&i.DeletedAt,
			&i.DeletedBy,
			&i.Attachments,
			&i.HasFiles,
			&i.RootID,
			&i.AlsoInChannel,
			&i.PinnedAt,
			&i.PinnedBy,
			&i.Title,
			&i.Tags,
			&i.LinkUrl,
			&i.LinkState,
			&i.Forward,
			&i.StickerID,
			&i.BurnSeconds,
			&i.TaskID,
			&i.SubmissionID,
			&i.Priority,
			&i.AckRequested,
			&i.Persistent,
			&i.AuthorName,
			&i.AuthorIsBot,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listSaved = `-- name: ListSaved :many
SELECT s.message_id, s.created_at AS saved_at, s.remind_at, s.done_at
FROM saved_messages s
JOIN messages m ON m.id = s.message_id AND m.deleted_at IS NULL
JOIN channel_members cm ON cm.channel_id = m.channel_id AND cm.user_id = $1
WHERE s.user_id = $1
ORDER BY s.created_at DESC
LIMIT 500
`

type ListSavedRow struct {
	MessageID pgtype.UUID        `json:"message_id"`
	SavedAt   time.Time          `json:"saved_at"`
	RemindAt  pgtype.Timestamptz `json:"remind_at"`
	DoneAt    pgtype.Timestamptz `json:"done_at"`
}

// ListSaved returns the saved messages of a user in channels they belong to,
// newest first.
func (q *Queries) ListSaved(ctx context.Context, userID pgtype.UUID) ([]ListSavedRow, error) {
	rows, err := q.db.Query(ctx, listSaved, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListSavedRow
	for rows.Next() {
		var i ListSavedRow
		if err := rows.Scan(
			&i.MessageID,
			&i.SavedAt,
			&i.RemindAt,
			&i.DoneAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listUnreadMessages = `-- name: ListUnreadMessages :many
SELECT x.id, x.channel_id, x.author_id, x.body, x.nonce, x.created_at, x.edited_at, x.attachments,
       x.root_id, x.also_in_channel, x.pinned_at, x.pinned_by, x.title, x.tags,
       x.link_url, x.link_state, x.forward, x.sticker_id, x.burn_seconds, x.task_id, x.submission_id,
       x.priority, x.ack_requested, x.persistent,
       u.display_name AS author_name, u.is_bot AS author_is_bot
FROM channel_members cm
JOIN channels c ON c.id = cm.channel_id AND c.archived_at IS NULL AND c.workspace_id = $1
CROSS JOIN LATERAL (
    SELECT m.id, m.channel_id, m.author_id, m.body, m.nonce, m.created_at, m.edited_at, m.deleted_at, m.deleted_by, m.attachments, m.has_files, m.root_id, m.also_in_channel, m.pinned_at, m.pinned_by, m.title, m.tags, m.link_url, m.link_state, m.forward, m.sticker_id, m.burn_seconds, m.task_id, m.submission_id, m.priority, m.ack_requested, m.persistent FROM messages m
    WHERE m.channel_id = c.id AND m.deleted_at IS NULL AND m.author_id <> $2
      AND (m.root_id IS NULL OR m.also_in_channel)
      AND (cm.last_read_id IS NULL OR m.id > cm.last_read_id)
    ORDER BY m.id DESC LIMIT 20) x
JOIN users u ON u.id = x.author_id
WHERE cm.user_id = $2
ORDER BY x.channel_id, x.id
`

type ListUnreadMessagesParams struct {
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	UserID      pgtype.UUID `json:"user_id"`
}

