const setThreadFollowing = `-- name: SetThreadFollowing :exec
INSERT INTO thread_follows (user_id, root_id, following, last_read_id)
VALUES ($1, $2, $3,
        (SELECT x.id FROM messages x WHERE x.root_id = $2 AND x.deleted_at IS NULL
         ORDER BY x.id DESC LIMIT 1))
ON CONFLICT (user_id, root_id) DO UPDATE SET following = EXCLUDED.following,
    last_read_id = coalesce(thread_follows.last_read_id, EXCLUDED.last_read_id)
`

type SetThreadFollowingParams struct {
	UserID    pgtype.UUID `json:"user_id"`
	RootID    pgtype.UUID `json:"root_id"`
	Following bool        `json:"following"`
}

// SetThreadFollowing records a choice to follow (from the latest reply on: older
// ones count as read) or to stop following a thread.
func (q *Queries) SetThreadFollowing(ctx context.Context, arg SetThreadFollowingParams) error {
	_, err := q.db.Exec(ctx, setThreadFollowing, arg.UserID, arg.RootID, arg.Following)
	return err
}

const threadSummaries = `-- name: ThreadSummaries :many
SELECT m.root_id::uuid AS root_id, count(*)::int AS reply_count, max(m.created_at)::timestamptz AS last_reply_at,
       (SELECT coalesce(jsonb_agg(jsonb_build_object('id', p.author_id, 'display_name', u.display_name)
                                  ORDER BY p.last DESC), '[]')
        FROM (SELECT x.author_id, max(x.created_at) AS last FROM messages x
              WHERE x.root_id = m.root_id AND x.deleted_at IS NULL
              GROUP BY x.author_id ORDER BY max(x.created_at) DESC LIMIT 3) p
        JOIN users u ON u.id = p.author_id)::jsonb AS participants
FROM messages m
WHERE m.root_id = ANY($1::uuid[]) AND m.deleted_at IS NULL
GROUP BY m.root_id
`

type ThreadSummariesRow struct {
	RootID       pgtype.UUID `json:"root_id"`
	ReplyCount   int32       `json:"reply_count"`
	LastReplyAt  time.Time   `json:"last_reply_at"`
	Participants []byte      `json:"participants"`
}

// ThreadSummaries counts the replies of messages and names their latest three
// repliers (newest first).
func (q *Queries) ThreadSummaries(ctx context.Context, rootIds []pgtype.UUID) ([]ThreadSummariesRow, error) {
	rows, err := q.db.Query(ctx, threadSummaries, rootIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ThreadSummariesRow
	for rows.Next() {
		var i ThreadSummariesRow
		if err := rows.Scan(
			&i.RootID,
			&i.ReplyCount,
			&i.LastReplyAt,
			&i.Participants,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const upsertSaved = `-- name: UpsertSaved :one
INSERT INTO saved_messages (user_id, message_id, remind_at, done_at)
VALUES ($1, $2, $3, CASE WHEN $4::boolean THEN now() END)
ON CONFLICT (user_id, message_id) DO UPDATE SET
    remind_at = EXCLUDED.remind_at,
    done_at = CASE WHEN $4::boolean THEN coalesce(saved_messages.done_at, now()) END
RETURNING user_id, message_id, created_at, remind_at, reminder_id, done_at
`

type UpsertSavedParams struct {
	UserID    pgtype.UUID        `json:"user_id"`
	MessageID pgtype.UUID        `json:"message_id"`
	RemindAt  pgtype.Timestamptz `json:"remind_at"`
	Done      bool               `json:"done"`
}

func (q *Queries) UpsertSaved(ctx context.Context, arg UpsertSavedParams) (SavedMessage, error) {
	row := q.db.QueryRow(ctx, upsertSaved,
		arg.UserID,
		arg.MessageID,
		arg.RemindAt,
		arg.Done,
	)
	var i SavedMessage
	err := row.Scan(
		&i.UserID,
		&i.MessageID,
		&i.CreatedAt,
		&i.RemindAt,
		&i.ReminderID,
		&i.DoneAt,
	)
	return i, err
}
